🐛 Describe the bug
#include <cuda_runtime.h>
#include <torch/torch.h>
#include <iostream>

int main() {
    std::cout << "CUDA device count: " << torch::cuda::device_count() << std::endl;
    std::cout << "CUDA is available: " << (torch::cuda::is_available() ? "Yes" : "No") << std::endl;
    std::cout << "cuDNN is available: " << (torch::cuda::cudnn_is_available() ? "Yes" : "No") <<        std::endl;
    int deviceCount;
    cudaGetDeviceCount(&deviceCount);
    std::cout << "Number of CUDA devices: " << deviceCount << std::endl;
    return 0;
}
produces: CUDA device count: 0 CUDA is available: No cuDNN is available: No Number of CUDA devices: 1
cuda runtime correctly identifies my device - rtx 4070. nvcc confirms 12.6 cuda toolkit, however neither debug, nor release version (libtorch-win-shared-with-deps-2.4.0+cu124.zip) can detect my cuda device. i downgraded cuda toolkit to 12.4 to match pytorch, but same effect.
Versions
libtorch-win-shared-with-deps-2.4.0+cu124.zip
